import{_ as o,o as r,c as n,a2 as a}from"./chunks/framework.Dxeykp0S.js";const p=JSON.parse('{"title":"学园介绍","description":"","frontmatter":{},"headers":[],"relativePath":"introduction.md","filePath":"introduction.md","lastUpdated":1787141678000}'),i={name:"introduction.md"};function s(e,t,l,g,h,c){return r(),n("div",null,[...t[0]||(t[0]=[a('<h1 id="学园介绍" tabindex="-1">学园介绍 <a class="header-anchor" href="#学园介绍" aria-label="Permalink to &quot;学园介绍&quot;">​</a></h1><h2 id="这是一个什么样的学园" tabindex="-1">这是一个什么样的学园 <a class="header-anchor" href="#这是一个什么样的学园" aria-label="Permalink to &quot;这是一个什么样的学园&quot;">​</a></h2><p>Python 技术学园是一个帮助你自我成长、系统掌握 Python 的园地。它的教学法完全参考了<a href="https://ife.baidu.com/introduction.html" target="_blank" rel="noreferrer">百度 Web 前端技术学园（IFE）</a>。</p><p>本学园从 Python 零基础出发，不设编程语言、技术栈或工作经验门槛。在这里，你会得到：</p><ul><li>对 Python 核心概念与语言特性的清晰讲解（缩进、GIL、可变默认参数、<code>is</code> vs <code>==</code>……）</li><li>有人给你<strong>精心挑选的阅读材料</strong>，而不是让你在搜索引擎里迷路</li><li>有人给你设计<strong>从易到难的实战任务</strong>，让你每写一行代码都知道它的用武之地</li></ul><h2 id="我们的教学法-向-ife-致敬" tabindex="-1">我们的教学法（向 IFE 致敬） <a class="header-anchor" href="#我们的教学法-向-ife-致敬" aria-label="Permalink to &quot;我们的教学法（向 IFE 致敬）&quot;">​</a></h2><p><strong>实践驱动。</strong> 以实践任务的练习为学习的主要驱动，通过实践与知识的搭配，让你知道每一个知识点的用武之地。</p><p><strong>先读后练。</strong> 每个任务都遵循 IFE 经典的页面结构：</p><ol><li><strong>前言 / 课程目标</strong> —— 今天要学什么，为什么学</li><li><strong>阅读学习</strong> —— 精选的官方文档与优质文章，先建立概念</li><li><strong>任务作业</strong> —— 动手的实战任务，有明确的实现步骤和验收标准</li><li><strong>自测问题</strong> —— 不写代码，用嘴巴（或键盘）回答，检验概念是否真的掌握</li><li><strong>总结</strong> —— 固定的学习笔记模板，记录用时、收获与疑问</li><li><strong>拓展阅读</strong> —— 给学有余力的你</li><li><strong>预告</strong> —— 下一节学什么</li></ol><p><strong>建立知识连接。</strong> 课程会先讲清 Python 本身，并在适合的地方提供 <strong>JS/Node ↔ Python 对照表</strong>。这些对照是辅助材料，不是学习前提。</p><p><strong>重视方法而非灌输。</strong> 我们希望你能够学习的不仅仅是知识，更希望你在这里找到、掌握自己的学习方法。一切的成长和进步一定依赖于你自己，也归功于你自己。</p><h2 id="班级设置" tabindex="-1">班级设置 <a class="header-anchor" href="#班级设置" aria-label="Permalink to &quot;班级设置&quot;">​</a></h2><p>学园按难度分为五个班级，从易到难逐级通关：</p><ul><li><strong>预备班 · 起跑准备</strong>：环境搭建与 Python 核心思维</li><li><strong>入门班 · 语言基础</strong>：语法、数据结构、函数、模块</li><li><strong>基础班 · 语言进阶</strong>：OOP、迭代器与生成器、装饰器、异常与 IO、包管理</li><li><strong>进阶班 · 工程能力</strong>：asyncio、并发模型、类型提示、FastAPI、pytest</li><li><strong>高级班 · Python 后端工程</strong>：ORM 与迁移、认证与安全、缓存与异步任务、可观测性、Docker 化、K8s 部署、毕业项目</li></ul><h2 id="学习建议" tabindex="-1">学习建议 <a class="header-anchor" href="#学习建议" aria-label="Permalink to &quot;学习建议&quot;">​</a></h2><ul><li><strong>不要跳级</strong>：任务经过精心设计，后面的任务依赖前面建立的直觉</li><li><strong>动手 &gt; 阅读</strong>：阅读材料是辅助，代码写够才算学会</li><li><strong>坚持记笔记</strong>：每个任务的&quot;总结&quot;环节请认真对待，它是 IFE 教学法的精髓</li><li><strong>允许犯错</strong>：在 Python 里踩坑是必经之路（比如可变默认参数），踩过才记得住</li></ul><p>← <a href="/python-practices/">首页</a> | <a href="/python-practices/preface">开学第一课</a> →</p>',17)])])}const u=o(i,[["render",s]]);export{p as __pageData,u as default};
